using System;using System.Collections.Generic;using Ashfall.Core;using UnityEngine;using Ashfall.Integration.Playable.Explosives;
namespace Ashfall.Integration.Playable.Networking {
 public sealed partial class R24LanSession {
  readonly Dictionary<string,string> grenadeAliases=new Dictionary<string,string>(StringComparer.Ordinal);
  string CanonicalGrenade(string local){string id;return grenadeAliases.TryGetValue(local,out id)?id:local;}
  string LocalSharedGrenade(R24LanGrenadeState row){if(peer.Lobby.State==R24LanLobbyState.Hosting)return row.Id;string local=R24LanWorldIdentity.LocalId(peer.Lobby.SessionId,peer.Lobby.MapManifestHash,"grenade",row.Id,row.Kind,1);grenadeAliases[local]=row.Id;return local;}
  long explosiveEpoch=-1;string publishedGrenade;int publishedGrenadeHand;double nextGrenadeEquipment;
  sealed class RootProjectileWorld:IR24LanProjectileWorld {readonly R24LanSession owner;internal RootProjectileWorld(R24LanSession owner){this.owner=owner;}bool Ignore(Collider collider){return owner.root!=null&&collider.transform.IsChildOf(owner.root.Rig.transform);}public bool Sweep(Float3 a,Float3 b,float radius,out float distance,out Float3 normal){distance=0;normal=new Float3(0,1,0);Vector3 from=new Vector3(a.X,a.Y,a.Z),to=new Vector3(b.X,b.Y,b.Z),delta=to-from;foreach(var overlap in Physics.OverlapSphere(from,radius,(1<<0)|(1<<8),QueryTriggerInteraction.Ignore))if(!Ignore(overlap))return true;distance=delta.magnitude;bool hit=false;if(distance>.000001f)foreach(var row in Physics.SphereCastAll(from,radius,delta/distance,distance,(1<<0)|(1<<8),QueryTriggerInteraction.Ignore)){if(Ignore(row.collider)||row.distance>distance)continue;hit=true;distance=row.distance;normal=V(row.normal);}return hit;}}
  void BindExplosivePresentation(){if(root.Explosives!=null){root.Explosives.ClearProjectiles();root.Explosives.SharedClaim=AllowGrenadeClaim;root.Explosives.SharedThrow=ThrowGrenade;root.Explosives.SharedDrop=DropGrenade;root.Explosives.SharedRocketVisual=root.Gameplay.CreateNetworkRocket;}root.Gameplay.SharedProjectileAuthority=true;}
  bool GrenadeRequest(string id,int hand,int action,Float3 at){double now=Time.realtimeSinceStartupAsDouble,last;string key="grenade/"+action+"/"+id;if(lootRequests.TryGetValue(key,out last)&&now-last<.25)return false;lootRequests[key]=now;PublishRawTracking();return peer.Lobby.RequestGrenade(CanonicalGrenade(id),Math.Max(0,hand-1),action,at);}
  bool AllowGrenadeClaim(string id,int hand){if(peer==null)return true;if(peer.Lobby.State==R24LanLobbyState.Connected&&!grenadeAliases.ContainsKey(id))return false;string local=id;id=CanonicalGrenade(id);R24LanGrenadeState row;if(!peer.Lobby.TryReadGrenade(id,out row)||row.Spent)return false;if(row.Owner==peer.Lobby.OwnActor)return true;if(row.Owner!=""||!root.LanWorldClaimIntent("grenade",local,hand-1))return false;GrenadeRequest(id,hand,0,row.Position);bool accepted=peer.Lobby.TryReadGrenade(id,out row)&&row.Owner==peer.Lobby.OwnActor;if(!accepted)TrackClaim("grenade",local,id,row.Kind,hand-1);return accepted;}
  bool ThrowGrenade(string id,int hand){if(peer==null)return false;GrenadeRequest(id,hand,1,new Float3());return false;}
  bool DropGrenade(string id,Vector3 at){if(peer==null)return true;if(peer.Lobby.State==R24LanLobbyState.Connected&&!grenadeAliases.ContainsKey(id))return false;id=CanonicalGrenade(id);R24LanGrenadeState row;if(!peer.Lobby.TryReadGrenade(id,out row)||row.Spent)return false;if(row.Owner=="")return true;if(row.Owner!=peer.Lobby.OwnActor)return false;GrenadeRequest(id,root.Explosives.HeldHand>0?root.Explosives.HeldHand:root.Gameplay.PrimaryHand+1,2,V(at));return peer.Lobby.TryReadGrenade(id,out row)&&row.Owner=="";}
  void SendRocket(string id,int hand){if(peer==null)return;PublishRawTracking();peer.Lobby.RequestRocket(CanonicalLoot(id),hand);}
  void PublishGrenadeEquipment(){if(peer==null||root.Explosives==null)return;string id=root.Explosives.HeldId;int hand=root.Explosives.HeldHand;double now=Time.realtimeSinceStartupAsDouble;if(publishedGrenade==id&&publishedGrenadeHand==hand&&now<nextGrenadeEquipment)return;if(id==null){if(publishedGrenade!=null)peer.Lobby.RequestGrenade(CanonicalGrenade(publishedGrenade),Math.Max(0,publishedGrenadeHand-1),4,new Float3());publishedGrenade=null;publishedGrenadeHand=0;}else if(peer.Lobby.RequestGrenade(CanonicalGrenade(id),Math.Max(0,hand-1),3,new Float3())){publishedGrenade=id;publishedGrenadeHand=hand;}nextGrenadeEquipment=now+.1;}
  void SyncExplosives(){if(peer==null||root==null||root.Explosives==null||!root.Ready)return;var lobby=peer.Lobby;var native=root.Explosives;if(explosiveEpoch!=lobby.Epoch){explosiveEpoch=lobby.Epoch;publishedGrenade=null;publishedGrenadeHand=0;native.ClearSharedProjectiles();}
   if(lobby.State==R24LanLobbyState.Hosting)foreach(string id in native.WorldItemIds){R24LanGrenadeState known;R23GrenadeItemState source;Vector3 at;Quaternion rotation;bool owned;if(!lobby.TryReadGrenade(id,out known)&&native.TryReadItem(id,out source)&&!source.Owned&&!source.Spent&&native.TryReadWorldItem(id,out at,out rotation,out owned))lobby.RegisterSharedGrenade(id,source.Kind,V(at));}
   foreach(var row in lobby.SharedGrenades){string local=LocalSharedGrenade(row);R23GrenadeItemState source;if(!native.TryReadItem(local,out source)){if(row.Spent)continue;native.SpawnWorldItem(local,row.Kind,1,new Vector3(row.Position.X,row.Position.Y,row.Position.Z),Quaternion.identity);}
    native.ReconcileNetworkItem(local,row.Owner==lobby.OwnActor&&!row.Spent,row.Spent);if(row.Owner==""&&!row.Spent)native.RepositionWorldItem(local,new Vector3(row.Position.X,row.Position.Y,row.Position.Z),lobby.State==R24LanLobbyState.Hosting);native.SetWorldItemVisible(local,!row.Spent&&(row.Owner==""||row.Owner==lobby.OwnActor));}
   foreach(string id in native.WorldItemIds){R24LanGrenadeState known;if(lobby.State==R24LanLobbyState.Connected&&!grenadeAliases.ContainsKey(id)||!lobby.TryReadGrenade(CanonicalGrenade(id),out known))native.SetWorldItemVisible(id,false);}
   var projectiles=lobby.SharedProjectiles;native.PresentSharedProjectiles(NonVehicleProjectiles(projectiles));foreach(var row in projectiles)if(row.Ended)lobby.AcknowledgeProjectilePresentation(row);
  }
 }
}
